import json,pathlib,collections,csv,hashlib
ROOT=pathlib.Path(__file__).resolve().parent;CAT=pathlib.Path(r'E:\l2-local\research\model-catalog');NEW=pathlib.Path(r'E:\l2-local\research\external-assets-round5-20261028')
g=json.loads((CAT/'gallery.json').read_text('utf-8'));models=[m for m in g['models'] if m.get('external_asset') and m['status']=='ready'];revs=json.loads((ROOT/'revisions.json').read_text('utf-8'));images=json.loads((ROOT/'image-validation.json').read_text('utf-8'));new=[m for m in models if m['batch'].endswith('Tanda 5')]
lines=['# Revisión de texturas — 28/10/2026','',f"{len(revs)} modelos reparados o mejorados, con {sum(len(r['changes']) for r in revs)} conexiones de mapas registradas. {images['images_checked']} imágenes externas verificadas; {len(images['invalid_images'])} inválidas después de la reparación de extracción.",'','[Comparación antes/después](before-after.jpg) · [Todos los modelos reparados](repaired-contact.jpg)','','## Qué se corrigió','','- BodyHighJacker: Windows tar no soportaba filtros RAR y había creado cuatro imágenes llenas de ceros. Reextraído con UnRAR; nueve archivos comprobados contra el CRC original. La ficha muestra model1; model2 sigue disponible en el paquete, sin ensamblar.','- Cinco Volt de Apex: recuperados color, normales y AO donde existe. No se reinterpretaron sus mapas especulares/gloss/ILM como metálico o emisión sin prueba.','- Bloody Rose: el GLB no tenía ningún material. Se conectó su atlas y mapas PBR a la malla con UV existente.','- Crimson Cup Plants: reparadas las equivalencias BaseColor/albedo, Alpha/opacity y Emission/emissive.','- Abomination: recuperadas referencias de cuerpo, ojos, cabello y bastón, además de normales. Su pose importada sigue requiriendo revisión.','- Hologram Police: recuperadas referencias rusas y extensiones `.tga.png`; falta el normal de la base.','- Old house: recuperadas tablas, puertas, ventanas, ladrillos, tejado y vigas por nombres de piezas; otros materiales siguen pendientes.','- Zeromus: se asignó el único atlas del paquete a las siete piezas como candidato. Sus rutas originales no permiten demostrar la asignación: sigue marcado para revisión UV.','- CATTO: atlas de cuerpo y cabello asignados por contenido visual; auxiliares/transparencias pendientes.','','## Conservación de datos','','Cada cambio conserva los bytes originales de geometría, pesos, huesos, matrices y animaciones. Se conservan los bufferViews originales y el BIN completo como prefijo idéntico. Solo se agregan imágenes y se modifican materiales; Bloody Rose recibe índices de material. Evidencia por revisión en `revisions.json`, originales en `before/`, hashes anteriores/nuevos y respaldo SQLite coherente en `rig-database-20261028/database-revisions`. Las revisiones materiales tienen su propia tabla `material_revisions`; la protección contra otros cambios de artefacto sigue activa.','','Los originales descargados no se modifican. Las miniaturas se renderizan desde el GLB reparado. La prueba del navegador decodifica las imágenes y comprueba el SHA del visor técnico. Esto no certifica un retarget ni la adaptación a Interlude. Los nombres de mapas no demuestran por sí solos la convención DirectX/OpenGL de cada normal.','','## Modelos modificados','','| Modelo | Conexiones registradas | Estado actual |','|---|---:|---|']
by={m['key']:m for m in models}
for r in revs:
 m=by[r['key']];lines.append(f"| [{m['title'].replace('|','/')}](http://127.0.0.1:32280/?model={m['key']}) | {len(r['changes'])} | {m['material_review']['status']} |")
lines+=['','## Casos pendientes','','| Modelo | Qué queda |','|---|---|']
for m in models:
 if m['material_review']['status']=='pending':
  slots=m['material_review'].get('missing_slots',[]);reason=m['material_review']['text'];lines.append(f"| {m['title'].replace('|','/')} | {reason}. Referencias: {', '.join(slots[:8]) or 'asignación/materiales auxiliares'}{'…' if len(slots)>8 else ''} |")
lines+=['','Airship y Robot no traen las imágenes externas que requieren algunos materiales. Medieval town se publicó expresamente sin texturas. Armor Cat es STL sin mapas/UV; no se presenta como reparación pendiente.','','## Evidencia','','- `inventory.json`: auditoría inicial de materiales GLB y archivos disponibles.','- `sources/*.json`: lectura de materiales, imágenes y conexiones FBX; incluye SHA del archivo fuente.','- `revisions.json`: cambios por material/slot, archivos fuente y SHA, prueba de conservación y respaldo.','- `image-validation.json`: integridad de formato de las imágenes extraídas.','- `body-rar-crc.json`: CRC de todos los archivos del RAR recuperado.','- `browser-verification.json`: carga real con Three.js, texturas decodificadas y acceso al índice técnico.','','## Nuevas descargas','','[Tanda 5 en el catálogo](http://127.0.0.1:32280/?batch=Assets%20externos%20%C2%B7%20Tanda%205)','',f'{len(new)} modelos nuevos publicados; se conservan autor, licencia y enlace de procedencia.']
(ROOT/'REVISION.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
if new:
 ns=['# Assets externos · Tanda 5 — 28/10/2026','','[Abrir catálogo](http://127.0.0.1:32280/?batch=Assets%20externos%20%C2%B7%20Tanda%205)','',f"{len(new)} modelos. {sum(m['asset_analysis']['bones']>0 for m in new)} con huesos; {sum(m['asset_analysis']['animations'] for m in new)} clips exportados.",'','| Modelo | Huesos | Clips | Materiales | Texturas |','|---|---:|---:|---:|---|']
 for m in new:ns.append(f"| [{m['title']}](http://127.0.0.1:32280/?model={m['key']}) | {m['asset_analysis']['bones']} | {m['asset_analysis']['animations']} | {m['material_count']} | {m['material_review']['status']} |")
 ns+=['','[Auditoría y reparaciones de texturas](../texture-audit-20261028/REVISION.md)','','No se modificó el cliente, el servidor ni la base del juego. Favoritos y anotaciones se conservan en el navegador del usuario.']
 (NEW/'REVISION.md').write_text('\n'.join(ns)+'\n',encoding='utf-8')
print('REPORTS',len(revs),len(new))
